insert into public.casualties_multiplier_items (id, type, battle, correct_casualties, year, source, difficulty, hint) values
  ('battle_232', 'CASUALTY_GUESS', 'Siege of Belgrade (1456)', 17000, 1456, 'Wikipedia infobox: Hungarian side 4,000 (Tucker: under 10,000); Ottoman 13,000 (Housley 1992 p.104; Babinger 4,000-5,000). Summed.', 2, 'Hungarian-Ottoman Wars'),
  ('battle_233', 'CASUALTY_GUESS', 'Battle of Towton', 11000, 1461, 'Wikipedia infobox: Yorkist 3,000-4,500 dead (Dean 2015 p.35); Lancastrian 6,000-8,500 dead (Ross 1997 p.37; Wolffe 2001 p.332). Midpoints summed.', 2, 'Wars of the Roses'),
  ('battle_234', 'CASUALTY_GUESS', 'Battle of Vaslui', 50000, 1475, 'Wikipedia article: Ottoman losses reported as 45,000 (Venetian and Polish records give 40,000-100,000; Pilat & Cristea 2006 p.149); Moldavian about 5,000 killed and wounded (infobox). Summed; contemporary figures are unreliable.', 3, 'Moldavian-Ottoman War'),
  ('battle_235', 'CASUALTY_GUESS', 'Battle of Breadfield', 38000, 1479, 'Wikipedia infobox citing Banlaky''s Hungarian military history (mek.oszk.hu): 8,000 Hungarian + 30,000 Ottoman and Wallachian dead, both Hungarian claims (the article text puts Hungarian losses nearer 3,000). Summed.', 3, 'Hungarian-Ottoman Wars'),
  ('battle_236', 'CASUALTY_GUESS', 'Battle of Fornovo', 4425, 1495, 'Wikipedia infobox: French 100-1,000 killed (Nolan 2006 p.304) + 200 wounded (Dupuy 1993 p.462); League 3,350-4,000 killed (Dupuy; Tucker 2010 p.361). Midpoints summed.', 3, 'Italian Wars'),
  ('battle_237', 'CASUALTY_GUESS', 'Battle of Garigliano', 4900, 1503, 'Wikipedia infobox (Tucker 2010 p.478): Spanish 900, French 4,000.', 3, 'Italian Wars'),
  ('battle_238', 'CASUALTY_GUESS', 'Battle of Ravenna', 10750, 1512, 'Wikipedia infobox: French-Ferrarese 3,000-4,500 dead; Spanish-Papal 7,000 dead (de Cadenas y Vicent 1978 p.233), wounded unknown; the article gives over 10,000 dead in all. Dead only, midpoints summed; the 17,000 civilians killed in the sack are excluded.', 3, 'War of the League of Cambrai'),
  ('battle_239', 'CASUALTY_GUESS', 'Battle of Flodden', 11100, 1513, 'Wikipedia infobox: English 1,500-1,700 killed (Paterson p.147); Scots 5,000-14,000 killed (Elliot pp.117-118). Midpoints summed.', 2, 'War of the League of Cambrai'),
  ('battle_240', 'CASUALTY_GUESS', 'Battle of Novara', 6500, 1513, 'Wikipedia infobox and article: French at least 5,000 casualties; Swiss 1,500 dead. Summed, so a lower bound.', 3, 'War of the League of Cambrai'),
  ('battle_241', 'CASUALTY_GUESS', 'Battle of Frankenhausen', 7006, 1525, 'Wikipedia article: peasant losses estimated at more than 7,000, Landsknecht casualties as low as six; the figures are described as unreliable.', 3, 'German Peasants'' War'),
  ('battle_242', 'CASUALTY_GUESS', 'First Ottoman Siege of Vienna', 16500, 1529, 'Wikipedia infobox: defenders more than 1,500 dead (civilian deaths unknown); Ottomans 15,000 wounded, dead or captured (Turnbull). Summed, so a lower bound.', 1, 'Ottoman-Habsburg War'),
  ('battle_243', 'CASUALTY_GUESS', 'Battle of Obertyn', 8002, 1531, 'Wikipedia infobox: Polish 256 killed; Moldavian 7,746 killed (1,000 more captured, excluded).', 3, 'Moldavian-Polish War'),
  ('battle_244', 'CASUALTY_GUESS', 'Battle of Cajamarca', 2502, 1532, 'Wikipedia infobox: Spanish 1 slave dead and one wounded; Inca 2,000-3,000 killed (7,000 more captured, excluded). Midpoint.', 2, 'Spanish conquest of Peru'),
  ('battle_245', 'CASUALTY_GUESS', 'Battle of Las Salinas', 129, 1538, 'Wikipedia infobox: Pizarro''s side 9 dead; Almagro''s side 120 dead (MacQuarrie 2008).', 3, 'Spanish conquest of Peru'),
  ('battle_246', 'CASUALTY_GUESS', 'Battle of Pinkie Cleugh', 10900, 1547, 'Wikipedia infobox (MacDougall pp.86-87): Scots 6,000-15,000 killed or wounded (2,000 more captured, excluded); English 200-600. Midpoints summed.', 3, 'Rough Wooing'),
  ('battle_247', 'CASUALTY_GUESS', 'Battle of Dreux', 7000, 1562, 'Wikipedia infobox: 4,000 casualties on one side and 3,000 on the other (1,500 more captured, excluded); the article text estimates 9,000-10,000 killed or wounded of 30,000 engaged. Infobox figures summed.', 3, 'French Wars of Religion'),
  ('battle_248', 'CASUALTY_GUESS', 'Great Siege of Malta', 32500, 1565, 'Wikipedia infobox: Ottomans 25,000-35,000 dead (Cassola; Bosio 30,000, Balbi 35,000); defenders at least 2,500. Midpoint summed.', 1, 'Ottoman-Habsburg War'),
  ('battle_249', 'CASUALTY_GUESS', 'Siege of Szigetvár', 27650, 1566, 'Wikipedia infobox: defenders 2,300-3,000 killed (Clodfelter 2017 p.26); Ottomans 20,000-30,000 total casualties (Varga 2019; Guldescu 1970). Midpoints summed.', 2, 'Ottoman-Habsburg War'),
  ('battle_250', 'CASUALTY_GUESS', 'Battle of Heiligerlee', 510, 1568, 'Wikipedia infobox and article: Spanish 460 dead; Nassau-Dutch side 50 dead or wounded, among them Adolf of Nassau.', 3, 'Eighty Years'' War'),
  ('battle_251', 'CASUALTY_GUESS', 'Battle of Moncontour', 9000, 1569, 'Wikipedia infobox (Tucker 2010 p.528; Butler 1907 p.13): Catholic 1,000 killed; Huguenot 8,000 killed (3,000 more captured, excluded).', 3, 'French Wars of Religion'),
  ('battle_252', 'CASUALTY_GUESS', 'Battle of Coutras', 2040, 1587, 'Wikipedia infobox: Huguenots 40 killed; Royalists 2,000 (300 of them nobles).', 3, 'French Wars of Religion'),
  ('battle_253', 'CASUALTY_GUESS', 'Battle of Ivry', 6500, 1590, 'Wikipedia infobox: Royalists 500; Catholic League and Spanish 6,000 killed or wounded (4,000 more captured, excluded).', 3, 'French Wars of Religion'),
  ('battle_254', 'CASUALTY_GUESS', 'Battle of Sisak', 8275, 1593, 'Wikipedia infobox: Ottomans about 8,000 killed or drowned (Luthar 2008); Habsburg-Croatian side 50-500 (Banlaky). Midpoints summed.', 3, 'Long Turkish War'),
  ('battle_255', 'CASUALTY_GUESS', 'Battle of Mezőkeresztes', 51500, 1596, 'Wikipedia infobox and article (Tucker 2010 p.547): Ottomans 20,000-30,000; Christians 23,000-30,000+. Midpoints summed.', 3, 'Long Turkish War'),
  ('battle_256', 'CASUALTY_GUESS', 'Battle of Nieuwpoort', 5450, 1600, 'Wikipedia article: Spanish 2,500-4,000 killed and wounded (600 more captured, excluded); Dutch-allied 1,700-2,700 (Van Nimwegen 2010 p.169; van der Hoeven 1997 p.106). Midpoints summed.', 3, 'Eighty Years'' War'),
  ('battle_257', 'CASUALTY_GUESS', 'Battle of Kircholm', 8300, 1605, 'Wikipedia infobox (Frost 2000 p.65; Barkman 1939; Sundberg 2002): Polish-Lithuanian 300 killed or wounded; Swedes about 8,000 killed, wounded or captured.', 3, 'Polish-Swedish War'),
  ('battle_258', 'CASUALTY_GUESS', 'Battle of Wimpfen', 4800, 1622, 'Wikipedia infobox: Protestant side 3,000+ and Catholic League-Spanish side 1,800+. Lower bounds summed.', 3, 'Thirty Years'' War'),
  ('battle_259', 'CASUALTY_GUESS', 'Battle of Lutter', 3700, 1626, 'Wikipedia article: Danish-allied army 3,000 dead or wounded (2,500 more surrendered next day, excluded); Tilly''s losses about 700 dead or wounded.', 3, 'Thirty Years'' War'),
  ('battle_260', 'CASUALTY_GUESS', 'Sack of Magdeburg', 26900, 1631, 'Wikipedia infobox (Wilson 2011 p.471): attackers 300 killed + 1,600 wounded; defenders and inhabitants 25,000.', 2, 'Thirty Years'' War'),
  ('battle_261', 'CASUALTY_GUESS', 'Battle of Rain', 4000, 1632, 'Wikipedia article: both sides about 2,000 killed or wounded (the Swedes took another 1,000 prisoner, excluded); Tilly was mortally wounded.', 3, 'Thirty Years'' War'),
  ('battle_262', 'CASUALTY_GUESS', 'Battle of the Alte Veste', 3400, 1632, 'Wikipedia infobox (Wilson 2018 p.34): Imperial 900; Swedish-Protestant 2,500.', 3, 'Thirty Years'' War'),
  ('battle_263', 'CASUALTY_GUESS', 'Battle of Nördlingen', 16500, 1634, 'Wikipedia infobox (David 2012 p.406; Picouet 2019 p.248; Pike 2023 p.174): Imperial-Spanish about 3,500 killed or wounded; Swedish-German 12,000-14,000 killed or captured.', 2, 'Thirty Years'' War'),
  ('battle_264', 'CASUALTY_GUESS', 'Battle of Wittstock', 8500, 1636, 'Wikipedia infobox (Wilson 2009 p.583): Swedes 3,500 dead or wounded; Imperial-Saxon 5,000 dead, wounded or captured.', 3, 'Thirty Years'' War'),
  ('battle_265', 'CASUALTY_GUESS', 'Battle of Rocroi', 10000, 1643, 'Wikipedia article: French about 4,000 (Tucker 2011 p.201); Spanish 6,000 casualties plus 4,000 captured per Melo''s report (infobox range 7,300-15,000 includes captured). Prisoners excluded.', 2, 'Thirty Years'' War'),
  ('battle_266', 'CASUALTY_GUESS', 'Battle of Jankau', 7500, 1645, 'Wikipedia article: Swedes 3,000-4,000 killed or wounded; Imperials about 4,000 killed or wounded (about 4,500 more taken prisoner, excluded).', 3, 'Thirty Years'' War'),
  ('battle_267', 'CASUALTY_GUESS', 'Battle of Saint Gotthard', 11000, 1664, 'Wikipedia infobox (Bodart 1908 p.88): Imperial-allied 2,000; Ottomans 8,000-10,000 (other estimates 14,000-22,000). Midpoint summed.', 3, 'Austro-Turkish War'),
  ('battle_268', 'CASUALTY_GUESS', 'Siege of Buda (1686)', 23000, 1686, 'Wikipedia infobox (Bodart 1908 p.107): Holy League about 20,000; Ottoman garrison about 3,000 killed (6,000 more captured, excluded).', 2, 'Great Turkish War'),
  ('battle_269', 'CASUALTY_GUESS', 'Second Battle of Mohács', 10000, 1687, 'Wikipedia infobox (Bodart 1908 p.108; Wentzcke 1943 p.286): Imperial 2,000 killed and wounded; Ottomans 8,000 killed and wounded (2,000 more captured, excluded).', 3, 'Great Turkish War'),
  ('battle_270', 'CASUALTY_GUESS', 'Battle of Slankamen', 32300, 1691, 'Wikipedia infobox: Habsburg-allied 7,300 (Turek); Ottoman 25,000.', 3, 'Great Turkish War'),
  ('battle_271', 'CASUALTY_GUESS', 'Battle of Blenheim', 25484, 1704, 'Wikipedia infobox: Allies 4,542 killed + 7,942 wounded; Franco-Bavarians 6,000 killed or drowned + 7,000 wounded (14,190 more captured, excluded).', 1, 'War of the Spanish Succession'),
  ('battle_272', 'CASUALTY_GUESS', 'Siege of Temesvár', 12597, 1716, 'Wikipedia infobox: Habsburg 2,407 killed + 4,190 wounded (Preyer 1995 pp.184-185); Ottoman 3,000 killed + 3,000 wounded (Hategan 2006 pp.206-209).', 3, 'Austro-Turkish War'),
  ('battle_273', 'CASUALTY_GUESS', 'Battle of Grocka', 13600, 1739, 'Wikipedia infobox (Bodart 1908 p.188): Habsburg 5,600 (2,350 killed, 2,850 wounded, 400 missing); Ottoman 8,000 killed and wounded.', 3, 'Austro-Turkish War'),
  ('battle_274', 'CASUALTY_GUESS', 'Battle of Delium', 1500, -424, 'Wikipedia article (Thucydides): about 1,000 Athenians and 500 Boeotians killed; the infobox lists about 1,200 Athenians.', 3, 'Peloponnesian War'),
  ('battle_275', 'CASUALTY_GUESS', 'Battle of Amphipolis', 607, -422, 'Wikipedia infobox (Thucydides): about 600 Athenians and 7 Spartans killed, among them both commanders, Cleon and Brasidas.', 3, 'Peloponnesian War'),
  ('battle_276', 'CASUALTY_GUESS', 'Battle of Mantinea (418 BC)', 1600, -418, 'Wikipedia infobox (Thucydides): Spartans about 300; Argives, Mantineans, Athenians and Aeginetans about 1,300 (800 Argives, 300 Mantineans, 200 Athenians and Aeginetans).', 3, 'Peloponnesian War'),
  ('battle_277', 'CASUALTY_GUESS', 'Battle of Nemea (394 BC)', 3900, -394, 'Wikipedia infobox (Xenophon): Spartans and allies 1,100 dead or wounded; Corinthian War coalition 2,800 dead or wounded.', 3, 'Corinthian War'),
  ('battle_278', 'CASUALTY_GUESS', 'Battle of the Granicus', 3615, -334, 'Wikipedia article and infobox: Macedonians 115 killed (Arrian); Persians 1,000 cavalry + 2,000-3,000 Greek mercenaries killed (2,000 more captured, excluded). Midpoint.', 2, 'Wars of Alexander'),
  ('battle_279', 'CASUALTY_GUESS', 'Battle of Sentinum', 33700, -295, 'Wikipedia infobox (Livy): Romans 8,700 killed; Samnites and Gauls 25,000 killed (8,000 more captured, excluded).', 3, 'Samnite Wars'),
  ('battle_280', 'CASUALTY_GUESS', 'Battle of Heraclea', 11000, -280, 'Wikipedia article (Hieronymus and Plutarch): Romans 7,000 dead (1,800 more taken prisoner), Pyrrhus 4,000; Dionysius gives 15,000 and 13,000.', 3, 'Pyrrhic War'),
  ('battle_281', 'CASUALTY_GUESS', 'Battle of Telamon', 46000, -225, 'Wikipedia infobox: Romans 6,000 killed (Perrett 1998 p.289); Gauls 40,000 killed (10,000 more captured, excluded).', 3, 'Roman-Gallic wars'),
  ('battle_282', 'CASUALTY_GUESS', 'Battle of Raphia', 12500, -217, 'Wikipedia article (Polybius): Ptolemaic 1,500 infantry + 700 cavalry killed; Seleucid just under 10,000 infantry + 300 cavalry killed (4,000 more captured, excluded).', 3, 'Fourth Syrian War'),
  ('battle_283', 'CASUALTY_GUESS', 'Battle of the Metaurus', 15000, -207, 'Wikipedia infobox: Romans 2,000-8,000 killed; Carthaginians 10,000 killed (5,400 more captured, excluded), Polybius''s figure (Livy''s are far higher). Midpoint.', 3, 'Second Punic War'),
  ('battle_284', 'CASUALTY_GUESS', 'Battle of Cynoscephalae', 8725, -197, 'Wikipedia article (Polybius, Livy): 8,000 Macedonians killed (5,000 more captured, excluded); Romans 700-750.', 3, 'Second Macedonian War'),
  ('battle_285', 'CASUALTY_GUESS', 'Battle of Magnesia', 15000, -190, 'Wikipedia article: modern estimates of 10,000 Seleucid and 5,000 Roman dead (Livy claims 53,000 and 349).', 3, 'Roman-Seleucid War'),
  ('battle_286', 'CASUALTY_GUESS', 'Battle of Arausio', 95000, -105, 'Wikipedia infobox (Duncan 2017 pp.126, 141; Livy via Valerius Antias): Romans 80,000 soldiers killed (about 40,000 camp followers excluded); Cimbri and Teutones 15,000.', 3, 'Cimbrian War'),
  ('battle_287', 'CASUALTY_GUESS', 'Battle of Pharsalus', 11200, -48, 'Wikipedia infobox: Caesarians 200-1,200 killed (Caesar says 200, Appian 1,200); Pompeians 6,000-15,000 killed (24,000 more captured, excluded). Midpoints summed.', 1, 'Caesar''s Civil War'),
  ('battle_288', 'CASUALTY_GUESS', 'Battle of Munda', 31500, -45, 'Wikipedia infobox and article: Caesarians 1,000 killed or missing + 500 wounded; Pompeians about 30,000 killed.', 3, 'Caesar''s Civil War'),
  ('battle_289', 'CASUALTY_GUESS', 'Siege of Masada', 960, 73, 'Wikipedia infobox (Josephus): 960 defenders dead, 7 survivors; Roman losses unrecorded. Traditionally dated late 72-early 73, or 73-74.', 2, 'First Jewish-Roman War'),
  ('battle_290', 'CASUALTY_GUESS', 'Battle of Mons Graupius', 10360, 83, 'Wikipedia infobox and article (Tacitus, Agricola): 10,000 Caledonians dead against 360 Roman auxiliaries. Dated AD 83 or 84.', 3, 'Roman conquest of Britain'),
  ('battle_291', 'CASUALTY_GUESS', 'Battle of Mursa Major', 57000, 351, 'Wikipedia article and infobox: Magnentius 24,000-30,000 casualties; Constantius about 30,000. Midpoint summed.', 3, 'Roman civil war of 350-353'),
  ('battle_292', 'CASUALTY_GUESS', 'Battle of Strasbourg', 8243, 357, 'Wikipedia infobox (Ammianus Marcellinus): Romans 243; Alamanni 8,000.', 3, 'Roman-Alamanni conflict'),
  ('battle_293', 'CASUALTY_GUESS', 'Battle of Adrianople', 15000, 378, 'Wikipedia infobox (Heather 1999 p.135; Williams & Friell p.18): Roman dead 10,000-15,000 or 20,000, roughly two-thirds of the army; Gothic losses unrecorded. Midpoint of 10,000-20,000.', 2, 'Gothic War')
